  await test('CodexSession — MCP tool steps carry mcp__<server>__<tool> + arguments, which the chat trail parses as a gateway tool', () => {
    const { CodexSession } = require('./codex-session');
    const vm = require('vm');
    // Event lines as emitted by codex-cli 0.162.1 `exec --json` for a call to the Stoa gateway.
    const recorded = [
      '{"type":"item.started","item":{"id":"item_0","type":"mcp_tool_call","server":"stoa","tool":"deepwiki__ask_question","arguments":{"repoName":"a/b","question":"q"},"result":null,"error":null,"status":"in_progress"}}',
      '{"type":"item.completed","item":{"id":"item_0","type":"mcp_tool_call","server":"stoa","tool":"deepwiki__ask_question","arguments":{"repoName":"a/b","question":"q"},"result":{"content":[{"type":"text","text":"ok"}],"structured_content":null},"error":null,"status":"completed"}}',
      '{"type":"item.completed","item":{"id":"item_1","type":"command_execution","command":"ls -la","status":"completed"}}',
      '{"type":"item.completed","item":{"id":"item_2","type":"file_change","path":"/tmp/x.txt","status":"completed"}}',
      '{"type":"item.completed","item":{"id":"item_3","type":"mcp_tool_call","tool":"orphan","arguments":null,"status":"failed"}}',
    ];
    const cs = new CodexSession({ workDir: '/tmp' });
    const steps = [];
    cs._currentOnTool = (t) => steps.push(t);
    for (const line of recorded) cs._handleEvent(JSON.parse(line));
    assert.deepStrictEqual(steps, [
      { name: 'mcp__stoa__deepwiki__ask_question', input: { repoName: 'a/b', question: 'q' } },
      { name: 'command_execution', input: { command: 'ls -la' } },
      { name: 'file_change', input: { command: '/tmp/x.txt' } },
      { name: 'mcp_tool_call', input: {} },
    ], 'one step per completed item; MCP name from server+tool, non-MCP steps unchanged, missing server falls back');

    const ctx = {};
    vm.runInNewContext(require('fs').readFileSync(path.join(__dirname, 'public/js/chat/trail.js'), 'utf8'), ctx);
    assert.deepStrictEqual({ ...ctx.parseStoaMcpTool(steps[0].name) }, { slug: 'deepwiki', tool: 'ask_question' }, 'chat labels the Codex step via deepwiki');
    assert.strictEqual(ctx.parseStoaMcpTool(steps[3].name), null, 'fallback step gets no label');
    assert.strictEqual(ctx.toolSummary(steps[0].name, steps[0].input), 'a/b', 'arguments feed the step summary');
  });

  await test('tool steps — stored per message for its own running agent only, capped, summary matches the chat trail', () => {
    const Database = require('better-sqlite3');
    const vm = require('vm');
    const fs = require('fs');
    const { MAX_STEPS, toolStepSummary, recordToolStep } = require('./lib/tool-steps');
    const mem = new Database(':memory:');
    mem.exec(fs.readFileSync(path.join(__dirname, 'db', 'schema.sqlite.sql'), 'utf8'));
    mem.exec(fs.readFileSync(path.join(__dirname, 'migrations', '20261023-message-tool-steps.sql'), 'utf8'));
    mem.exec(`INSERT INTO actors (id, type, name) VALUES (1, 'ai', 'A'), (2, 'ai', 'B');
      INSERT INTO rooms (id, title, created_by) VALUES (1, 'r', 1);
      INSERT INTO room_participants (id, room_id, actor_id) VALUES (10, 1, 1), (20, 1, 2);
      INSERT INTO messages (id, room_id, participant_id, content, state) VALUES
        (100, 1, 10, '', 'streaming'), (101, 1, 10, 'x', 'complete'), (102, 1, 20, '', 'streaming');`);
    const steps = id => JSON.parse(mem.prepare('SELECT tool_steps FROM messages WHERE id=?').get(id).tool_steps || '[]');

    assert.strictEqual(recordToolStep(mem, { messageId: 100, actorId: 1, tool: { name: 'Bash', input: { command: 'ls', description: 'list' } } }), true);
    assert.strictEqual(recordToolStep(mem, { messageId: 100, actorId: 1, tool: { name: 'mcp__stoa__deepwiki__ask_question', input: { repoName: 'a/b', secret: 1 } } }), true);
    assert.deepStrictEqual(steps(100), [{ name: 'Bash', summary: 'ls' }, { name: 'mcp__stoa__deepwiki__ask_question', summary: 'a/b' }], 'only name + one-line summary kept, in order');
    assert.strictEqual(recordToolStep(mem, { messageId: 102, actorId: 1, tool: { name: 'Bash', input: {} } }), false, 'another actor\'s message is refused');
    assert.strictEqual(recordToolStep(mem, { messageId: 101, actorId: 1, tool: { name: 'Bash', input: {} } }), false, 'a finished message is refused');
    assert.strictEqual(recordToolStep(mem, { messageId: 100, actorId: 1, tool: { input: {} } }), false, 'nameless tool is ignored');
    assert.deepStrictEqual([steps(101), steps(102)], [[], []]);
    for (let i = 0; i < MAX_STEPS + 5; i++) recordToolStep(mem, { messageId: 100, actorId: 1, tool: { name: 'Read', input: { file_path: '/f' + i } } });
    assert.strictEqual(steps(100).length, MAX_STEPS, 'capped');

    const ctx = {};
    vm.runInNewContext(fs.readFileSync(path.join(__dirname, 'public/js/chat/trail.js'), 'utf8'), ctx);
    const cases = [['Bash', { command: 'x'.repeat(100) }], ['Read', { file_path: '/a' }], ['Grep', { pattern: 'p', path: '/q' }],
      ['mcp__x', { n: 3, q: 'first' }], ['Edit', { old_string: 'o' }], ['Write', null], ['Other', {}], ['Bash', { command: 'x'.repeat(64) }]];
    for (const [n, input] of cases) assert.strictEqual(toolStepSummary(n, input), ctx.toolSummary(n, input), `summary parity for ${n}`);
    assert.deepStrictEqual(JSON.parse(JSON.stringify(ctx.parseSavedToolSteps(JSON.stringify([{ name: 'Bash', summary: 'ls' }, { name: '' }, null, { name: 'Read', summary: 5 }])))),
      [{ name: 'Bash', summary: 'ls' }, { name: 'Read', summary: '' }], 'client drops malformed saved steps');
    assert.deepStrictEqual([...ctx.parseSavedToolSteps('not json')], []);
    assert.deepStrictEqual([...ctx.parseSavedToolSteps('{"name":"Bash"}')], []);
  });

  await test('sub-agent avatar — no own photo falls back to a label seal (never the parent photo), live refresh repaints only that sub-agent', () => {
    const vm = require('vm');
    const fs = require('fs');
    const el = tag => ({ tagName: tag.toUpperCase(), style: {}, dataset: {}, children: [], replaceChildren(...c) { this.children = c; } });
    const rendered = [];
    const ctx = {
      document: { createElement: tag => { const e = el(tag); if (tag === 'div') rendered.push(e); return e; } },
      makeAvatar: (name, color, url) => ({ parentAvatar: { name, color, url } }),
      allActors: [{ id: 1, name: 'Ara' }, { id: 2, name: 'Idris' }],
    };
    vm.runInNewContext(fs.readFileSync(path.join(__dirname, 'public/js/chat/sub-agent-avatar.js'), 'utf8'), ctx);
    const only = w => w.children[0];

    assert.deepStrictEqual(ctx.makeAvatarEl('Ara', '#a00', '/uploads/avatar/ara.png', 36, null), { parentAvatar: { name: 'Ara', color: '#a00', url: '/uploads/avatar/ara.png' } }, 'a plain agent keeps its own avatar');

    const bare = only(ctx.makeAvatarEl('Ara', '#a00', '/uploads/avatar/ara.png', 36, 'vera', null, null, null));
    assert.strictEqual(bare.tagName, 'SPAN', 'no image element: the parent photo is never used');
    assert.strictEqual(bare.src, undefined);
    assert.strictEqual(bare.className, 'h-seal');
    assert.strictEqual(bare.textContent, 'V', 'seal shows the label initial, not the parent initial');
    assert.strictEqual(bare.style.background, '#a00', 'parent colour is allowed as the seal colour');
    assert.strictEqual(bare.style.width, '36px');

    const own = only(ctx.makeAvatarEl('Ara', '#a00', '/uploads/avatar/ara.png', 28, 'Vera', '#0a0', 'Ψ', null));
    assert.deepStrictEqual([own.textContent, own.style.background], ['Ψ', '#0a0'], 'own symbol and colour win');
    assert.strictEqual(only(ctx.makeAvatarEl('Ara', null, null, 20, 'Vera', null, null, null)).style.background, '#888');

    const photo = only(ctx.makeAvatarEl('Ara', '#a00', '/uploads/avatar/ara.png', 40, 'Vera', null, null, '/uploads/avatar/avatar-sa-852-1.png'));
    assert.deepStrictEqual([photo.tagName, photo.src, photo.alt], ['IMG', '/uploads/avatar/avatar-sa-852-1.png', 'Vera']);

    rendered.length = 0;
    const vera = ctx.makeAvatarEl('Ara', '#a00', null, 36, 'Vera', null, null, null);
    const kenji = ctx.makeAvatarEl('Ara', '#a00', null, 36, 'Kenji', null, null, null);
    const otherVera = ctx.makeAvatarEl('Idris', '#00a', null, 28, 'Vera', null, null, null);
    const root = { querySelectorAll: sel => { assert.strictEqual(sel, '.h-sa-avatar-wrap[data-sa-label]'); return rendered.filter(w => w.dataset.saLabel); } };
    ctx.refreshSubAgentAvatars({ id: 852, parent_actor_id: 1, label: 'Vera', avatar_url: '/uploads/avatar/avatar-sa-852-2.png' }, root);
    assert.deepStrictEqual([only(vera).tagName, only(vera).src, /width:36px/.test(only(vera).style.cssText)], ['IMG', '/uploads/avatar/avatar-sa-852-2.png', true], 'the updated sub-agent is repainted at its rendered size');
    assert.strictEqual(only(kenji).tagName, 'SPAN', 'a sibling sub-agent is untouched');
    assert.strictEqual(only(otherVera).tagName, 'SPAN', 'same label under another parent is untouched');
    ctx.refreshSubAgentAvatars({ id: 852, parent_actor_id: 1, label: 'Vera', avatar_url: null, avatar_color: '#0a0', avatar_symbol: null }, root);
    assert.deepStrictEqual([only(vera).tagName, only(vera).textContent, only(vera).style.background], ['SPAN', 'V', '#0a0'], 'removing the photo falls back to the seal, not the parent photo');
    ctx.refreshSubAgentAvatars({ id: 9, parent_actor_id: 99, label: 'Vera', avatar_url: '/x.png' }, root);
    assert.strictEqual(only(vera).tagName, 'SPAN', 'unknown parent repaints nothing');
  });

  await test('schedules panel — every form spec passes server validation unchanged, summaries and next run read naturally', () => {
    const vm = require('vm');
    const fs = require('fs');
    const { validateScheduleSpec } = require('./lib/schedule');
    const ctx = {};
    vm.runInNewContext(fs.readFileSync(path.join(__dirname, 'public/js/rooms/schedules.js'), 'utf8'), ctx);
    const js = v => JSON.stringify(v);
    const form = (patch) => Object.assign(ctx.schedDefaultForm([{ actor_id: 7 }]), { task: 'post the morning summary' }, patch);
    const forms = [
      form({ type: 'interval', every: 90 }),
      form({ type: 'daily', at: '07:30', tz: 'Asia/Jakarta' }),
      form({ type: 'weekly', at: '09:00', tz: 'Europe/London', days: new Set([5, 1, 3]) }),
      form({ type: 'monthly', at: '23:59', tz: 'UTC', day: 31 }),
      form({ type: 'yearly', at: '00:00', tz: 'America/New_York', month: 2, yday: 29 }),
    ];
    for (const f of forms) {
      assert.strictEqual(f.target, 7, 'default target is the first agent');
      assert.strictEqual(ctx.schedValidateForm(f), '', `${f.type} form is valid`);
      const spec = ctx.schedSpecFromForm(f);
      const v = validateScheduleSpec(JSON.parse(js(spec)));
      assert.ok(v.ok, `${f.type}: ${v.error}`);
      assert.strictEqual(js(v.spec), js(spec), `${f.type}: server normalization is a no-op on what the panel sends`);
      const back = ctx.schedSpecFromForm(ctx.schedFormFromSchedule({ id: 1, target_actor_id: 7, task: 't', schedule_spec: v.spec }));
      assert.strictEqual(js(back), js(spec), `${f.type}: edit form round-trips the stored spec`);
    }
    assert.strictEqual(js(ctx.schedSpecFromForm(forms[2]).days), '[1,3,5]', 'weekdays sent sorted, Sunday = 0');

    const S = ctx.schedSummary;
    assert.deepStrictEqual([15, 60, 90, 120].map(m => S({ type: 'interval', every_minutes: m })),
      ['every 15 min', 'every hour', 'every 1 h 30 min', 'every 2 hours']);
    assert.strictEqual(S({ type: 'weekly', at: '09:00', tz: 'Asia/Jakarta', days: [1, 3, 5] }), 'every Mon, Wed, Fri at 09:00 WIB');
    assert.strictEqual(S({ type: 'weekly', at: '09:00', tz: 'Asia/Jakarta', days: [1, 2, 3, 4, 5] }), 'every weekday at 09:00 WIB');
    assert.strictEqual(S({ type: 'weekly', at: '09:00', tz: 'UTC', days: [0, 1] }), 'every Mon, Sun at 09:00 UTC', 'Monday-first order');
    assert.strictEqual(S({ type: 'weekly', at: '08:00', tz: 'Europe/London', days: [0, 6] }, true), 'weekends · 08:00 London');
    assert.deepStrictEqual([1, 2, 3, 11, 12, 13, 21, 22, 31].map(d => S({ type: 'monthly', at: '07:00', tz: 'UTC', day: d }, true).split(' · ')[1]),
      ['1st', '2nd', '3rd', '11th', '12th', '13th', '21st', '22nd', '31st']);
    assert.strictEqual(S({ type: 'yearly', at: '09:00', tz: 'Asia/Makassar', month: 8, day: 17 }), 'every year on Aug 17 at 09:00 WITA');
    assert.strictEqual(S({ type: 'nope' }), 'unknown schedule');
    assert.strictEqual(ctx.schedSummaryNote({ type: 'monthly', day: 30 }), 'months without a 30th run on their last day');
    assert.strictEqual(ctx.schedSummaryNote({ type: 'monthly', day: 28 }), '');
    assert.strictEqual(ctx.schedSummaryNote({ type: 'yearly', month: 2, day: 29 }), 'non-leap years run on Feb 28');

    assert.strictEqual(ctx.schedValidateForm(form({ type: 'weekly', days: new Set() })), 'pick at least one day');
    assert.strictEqual(ctx.schedValidateForm(form({ type: 'interval', every: 4 })), 'interval must be 5–1440 minutes');
    assert.strictEqual(ctx.schedValidateForm(form({ type: 'daily', at: '' })), 'pick a time');
    assert.strictEqual(ctx.schedValidateForm(form({ task: '   short   ' })), 'task needs at least 10 characters');
    assert.strictEqual(ctx.schedValidateForm(Object.assign(form({}), { target: null })), 'pick an agent');

    assert.strictEqual(ctx.schedParseUtc('2026-10-24 02:00:00').toISOString(), '2026-10-24T02:00:00.000Z', 'SQLite UTC timestamps parse as UTC');
    const daily = { type: 'daily', at: '09:00', tz: 'Asia/Jakarta' };
    assert.ok(ctx.schedNextRunText({ enabled: 1, next_run_at: '2026-10-27 02:00:00', schedule_spec: daily }).startsWith('next Tue 27 Oct, 09:00 WIB · '),
      'next run shown in the schedule\'s own time zone');
    assert.strictEqual(ctx.schedNextRunText({ enabled: 0, next_run_at: null, schedule_spec: daily }), 'paused');
  });

  await test('update panel — blocker/unsupported codes map to readable reasons, outcome toast shown once, badge follows behind', () => {
    const vm = require('vm');
    const fs = require('fs');
    const toasts = [];
    const store = {};
    const nav = { title: '', attrs: {}, cls: new Set(),
      classList: { toggle(c, on) { on ? nav.cls.add(c) : nav.cls.delete(c); } },
      setAttribute(k, v) { nav.attrs[k] = v; } };
    const el = () => { const e = { textContent: '', cls: [], attrs: {}, kids: [],
      classList: { add: c => e.cls.push(c) }, setAttribute(k, v) { e.attrs[k] = v; }, appendChild(k) { e.kids.push(k); } }; return e; };
    const ctx = {
      document: { getElementById: id => (id === 'nav-server' ? nav : null), createElement: el },
      localStorage: { getItem: k => (k in store ? store[k] : null), setItem: (k, v) => { store[k] = String(v); } },
      showToast: (msg, opts) => toasts.push({ msg, error: !!opts?.error }),
    };
    vm.runInNewContext(fs.readFileSync(path.join(__dirname, 'public/js/settings/update.js'), 'utf8'), ctx);
    const R = ctx.sUpdateBlockReason;
    const base = { supported: true, reason: null, behind: 3, blockers: [] };
    assert.strictEqual(R(base), null, 'behind with no blockers can update');
    assert.match(R({ ...base, supported: false, reason: 'docker' }), /docker/);
    assert.match(R({ ...base, supported: false, reason: 'not_git' }), /not a git checkout/);
    assert.match(R({ ...base, supported: false, reason: 'no_process_manager' }), /process manager/);
    assert.strictEqual(R({ ...base, supported: false, reason: 'brand_new' }), 'brand_new', 'unknown code shown as-is');
    assert.match(R({ ...base, blockers: ['dirty_tree'] }), /tracked files have uncommitted/);
    assert.match(R({ ...base, blockers: ['diverged'] }), /fast-forward/);
    assert.match(R({ ...base, blockers: ['not_default_branch'] }), /another branch/);
    assert.match(R({ ...base, blockers: ['update_running'] }), /already running/);
    assert.strictEqual(R({ ...base, blockers: ['constructor'] }), 'constructor', 'prototype keys are not codes');
    assert.ok(ctx.sUpdateIsBusy({ update: { state: 'running' } }) && ctx.sUpdateIsBusy({ update: { state: 'restarting' } }));
    assert.ok(!ctx.sUpdateIsBusy({ update: { state: 'failed' } }), 'a failed update can be retried');
    assert.match(R({ ...base, blockers: ['up_to_date', 'dirty_tree'] }), /tracked files have uncommitted/, 'a real blocker outranks up_to_date');
    assert.strictEqual(R({ ...base, behind: 0 }), 'already up to date.');
    assert.strictEqual(ctx.sUpdateVersionLabel({ sha: 'abc1234', version: '0.68.0' }), 'v0.68.0 · abc1234');
    assert.strictEqual(ctx.sUpdateVersionLabel(null), '—');

    const rolled = { ...base, current: { sha: 'e2f45ac', version: '0.67.1' },
      update: { state: 'idle', last_result: { ok: false, rolled_back: true, from: 'e2f45ac', error: 'migration failed', at: '2026-10-25T07:00:00Z' } } };
    ctx.sUpdateApply(rolled);
    ctx.sUpdateApply(rolled);
    assert.strictEqual(toasts.length, 1, 'rollback announced once across reconnects');
    assert.ok(toasts[0].error && /rolled back to e2f45ac: migration failed/.test(toasts[0].msg), toasts[0].msg);
    assert.ok(nav.cls.has('has-update') && /update available/.test(nav.attrs['aria-label']), 'badge on while behind');
    ctx.sHandleUpdateAvailable({ latest: { sha: 'abc1234' }, behind: 0 });
    assert.ok(!nav.cls.has('has-update') && nav.attrs['aria-label'] === 'Server', 'badge cleared when up to date');
    ctx.sUpdateApply({ ...rolled, update: { state: 'idle', last_result: { ok: true, at: '2026-10-25T08:00:00Z' } } });
    assert.strictEqual(toasts.length, 2);
    assert.ok(!toasts[1].error && /updated to v0.67.1/.test(toasts[1].msg), 'a newer successful result is announced');

    for (const step of ['fetch', 'merge', 'smoke']) ctx.sHandleUpdateProgress({ type: 'update_progress', state: 'running', step });
    ctx.sHandleUpdateProgress({ type: 'update_progress', state: 'failed', step: 'smoke', error: 'smoke: exited (1)' });
    const steps = ctx.sUpdateMakeProgress({ state: 'failed', step: 'smoke' }).kids.map(k => `${k.textContent}:${k.cls.join(',')}`);
    assert.deepStrictEqual(steps, ['fetch:is-done', 'apply commits:is-done', 'install dependencies · skipped:is-skipped',
      'test boot:is-failed', 'restart:'], 'unchanged lockfile shows install as skipped, not done');
  });

