    ws6.send(JSON.stringify({ type: 'agent_connect', actor_id: wrongActorId, secret: wrongSecret }));
    await ready6;
    // Intercept check_harnesses on primary ws, forward request_id to wrong agent
    let capturedRequestId = null;
